CREATE FUNCTION proof_collection(op integer,command jsonb) RETURNS jsonb LANGUAGE sql AS $$
 SELECT execute_sales_collection_command('10000000-0000-0000-0000-000000000001','20000000-0000-0000-0000-000000000001',('70000000-0000-0000-0000-'||lpad(op::text,12,'0'))::uuid,command,
 proof_governance(command->>'action',CASE command->>'action' WHEN 'collection.save_terms' THEN 'sales_save_collection_terms' WHEN 'collection.stage_import' THEN 'sales_stage_collection_import' WHEN 'collection.record_receipt' THEN 'sales_record_manual_payment' WHEN 'collection.reverse_receipt' THEN 'sales_reverse_manual_payment' ELSE 'sales_commit_collection_import' END)) $$;
CREATE TEMP TABLE proof_commands(name text PRIMARY KEY,command jsonb,result jsonb);
INSERT INTO proof_commands VALUES('terms','{"action":"collection.save_terms","agreement_id":"40000000-0000-0000-0000-000000000001","expected_version":0,"terms":{"schema_version":1,"kind":"installment","currency":"usd","total_cents":1000,"anchor_date":"2026-01-31","cadence":"monthly","count":3,"end_date":null,"dates":[],"deposit_cents":null,"late_fee":{"fixed_cents":0,"rate_bps":0,"grace_days":0,"agreement_basis":null},"interest":{"annual_bps":0,"agreement_basis":null}}}',NULL);
