CREATE FUNCTION proof_fail_rail() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.source_id='70000000-0000-0000-0000-000000000071' THEN RAISE EXCEPTION 'Forced proof receipt failure' USING ERRCODE='22023';END IF;RETURN NEW;END $$;
CREATE TRIGGER proof_forced_rail_failure BEFORE INSERT ON paige_workspace_events FOR EACH ROW EXECUTE FUNCTION proof_fail_rail();
SET LOCAL ROLE service_role;
SELECT proof_denied($q$SELECT proof_collection(71,(SELECT jsonb_build_object('action','collection.commit_import','batch_id',result#>>'{batch,id}','expected_digest',result#>>'{batch,content_digest}') FROM proof_commands WHERE name='rail-failure'))$q$,'22023','actual Rail failure rolls back whole import');
RESET ROLE;
