SELECT proof_denied($q$SELECT proof_collection(54,(SELECT jsonb_set(jsonb_set(command,'{expected_version}','2'),'{received_at}','"2100-01-01T00:00:00.000Z"') FROM proof_commands WHERE name='record-receipt'))$q$,'22023','imported receipt future refused');
